window.products.push({"id":788,"name":"Rebel Cross Ring","category":"jewelry","retail price":29.0,"sale price":29.0,"image":"https://cdn.shopify.com/s/files/1/1782/4093/files/2be1248851dff548e9330d99e4eae52b_b5fa6ebd-2a99-45bd-aac7-ccec33513d23.jpg?v=1760348458","description":"Let this be your anchor. The Rebel Cross Ring reimagines a timeless form with a raw, modern edge. A bold cross shape is rendered in a textured silver tone metal that gives a handcrafted, authentic vibe. Studded with six deep olive green faceted stones, the design is both gritty and luminous. Wear it as a powerful, tangible reminder of your own strength and the path you forge for yourself.","images":["https://cdn.shopify.com/s/files/1/1782/4093/files/2be1248851dff548e9330d99e4eae52b_b5fa6ebd-2a99-45bd-aac7-ccec33513d23.jpg?v=1760348458","https://m.media-amazon.com/images/I/61qOG0oAmSL._AC_SY675_.jpg","https://www.watch-connection.com/cdn/shop/files/marc-jacobs-mj3572-130459_e21fae82-81b0-4769-931b-a3a879609dad_1024x1024.jpg?v=1776515768","https://www.watch-connection.com/cdn/shop/files/6511aae4-d7e9-404d-9182-5041b63689c7_1.1340d8aa6a714213cdee239fb2a8db3c_1024x1024.jpg?v=1776515773","https://www.watch-connection.com/cdn/shop/files/60823b8662758-23042021101414_1024x1024.jpg?v=1776515781","https://www.watch-connection.com/cdn/shop/files/dong-ho-hieu-mj3572_25052020120746_1024x1024.jpg?v=1776515809"],"specifications":{"brand":"En Route Jewelry","material":"See source product page"},"sku":"BM-0788","productType":"Jewelry","inventory":100,"age_group":"Adult","gender":"Unisex","source_url":"https://enroutejewelry.com/products/rebel-cross-ring"});
